import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public final class Solution {
    public static final class Item {
        public final int id;
        public final String title;

        public Item(int id, String title) {
            this.id = id;
            this.title = title;
        }
    }

    public static List<Item> upsert(List<Item> current, Item item) {
        validate(current);
        validateItem(item);
        List<Item> copy = new ArrayList<>(current);
        boolean replaced = false;
        for (int i = 0; i < copy.size(); i++) {
            if (copy.get(i).title.equals(item.title)) {
                copy.set(i, item);
                replaced = true;
                break;
            }
        }
        if (!replaced) {
            copy.add(item);
        }
        copy.sort(Comparator.comparingInt(value -> value.id));
        return Collections.unmodifiableList(copy);
    }

    public static Item findById(List<Item> current, int id) {
        validate(current);
        if (id <= 0) {
            throw new IllegalArgumentException("id must be positive");
        }
        for (Item item : current) {
            if (item.id == id) {
                return item;
            }
        }
        return null;
    }

    private static void validate(List<Item> items) {
        if (items == null) {
            throw new IllegalArgumentException("list must not be null");
        }
        Set<Integer> ids = new HashSet<>();
        for (Item item : items) {
            validateItem(item);
            if (!ids.add(item.id)) {
                throw new IllegalArgumentException("duplicate id");
            }
        }
    }

    private static void validateItem(Item item) {
        if (item == null || item.id <= 0 || item.title == null || item.title.trim().isEmpty()) {
            throw new IllegalArgumentException("invalid item");
        }
    }
}

