import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        Solution.Item one = new Solution.Item(1, "one");
        Solution.Item two = new Solution.Item(2, "two");
        Solution.Item three = new Solution.Item(3, "three");

        expectIllegalArgument(() -> Solution.upsert(null, one));
        expectIllegalArgument(() -> Solution.upsert(new ArrayList<Solution.Item>(), null));
        expectIllegalArgument(() -> Solution.upsert(new ArrayList<Solution.Item>(), new Solution.Item(0, "zero")));
        expectIllegalArgument(() -> Solution.upsert(new ArrayList<Solution.Item>(), new Solution.Item(1, null)));
        expectIllegalArgument(() -> Solution.upsert(new ArrayList<Solution.Item>(), new Solution.Item(1, "  \t")));
        expectIllegalArgument(() -> Solution.findById(null, 1));
        expectIllegalArgument(() -> Solution.findById(Collections.<Solution.Item>emptyList(), 0));
        expectIllegalArgument(() -> Solution.findById(Collections.<Solution.Item>emptyList(), -1));

        List<Solution.Item> current = new ArrayList<>(Arrays.asList(three, one));
        List<Solution.Item> snapshot = new ArrayList<>(current);
        List<Solution.Item> inserted = Solution.upsert(current, two);
        assertSameContents(snapshot, current);
        assertIds(inserted, 1, 2, 3);
        assertSame(one, inserted.get(0));
        assertSame(two, inserted.get(1));
        assertSame(three, inserted.get(2));
        expectUnsupported(() -> inserted.add(new Solution.Item(4, "four")));

        Solution.Item replacement = new Solution.Item(2, "TWO");
        List<Solution.Item> replaced = Solution.upsert(inserted, replacement);
        assertIds(replaced, 1, 2, 3);
        assertSame(replacement, replaced.get(1));
        assertSame(two, inserted.get(1));

        List<Solution.Item> emptyResult = Solution.upsert(Collections.<Solution.Item>emptyList(), one);
        assertIds(emptyResult, 1);
        assertSame(one, Solution.findById(emptyResult, 1));
        assertNull(Solution.findById(emptyResult, 2));

        List<Solution.Item> duplicates = Arrays.asList(one, new Solution.Item(1, "duplicate"));
        expectIllegalArgument(() -> Solution.upsert(duplicates, two));
        expectIllegalArgument(() -> Solution.findById(duplicates, 1));

        List<Solution.Item> nullElement = new ArrayList<>();
        nullElement.add(null);
        expectIllegalArgument(() -> Solution.upsert(nullElement, one));
        expectIllegalArgument(() -> Solution.findById(nullElement, 1));

        List<Solution.Item> invalidId = Arrays.asList(new Solution.Item(-2, "bad"));
        expectIllegalArgument(() -> Solution.upsert(invalidId, one));
        expectIllegalArgument(() -> Solution.findById(invalidId, 1));

        List<Solution.Item> invalidTitle = Arrays.asList(new Solution.Item(9, " "));
        expectIllegalArgument(() -> Solution.upsert(invalidTitle, one));
        expectIllegalArgument(() -> Solution.findById(invalidTitle, 1));
    }

    private static void assertIds(List<Solution.Item> items, int... ids) {
        if (items.size() != ids.length) throw new AssertionError("unexpected list size");
        for (int i = 0; i < ids.length; i++) {
            if (items.get(i).id != ids[i]) throw new AssertionError("wrong id at index " + i);
        }
    }

    private static void assertSameContents(List<Solution.Item> expected, List<Solution.Item> actual) {
        if (expected.size() != actual.size()) throw new AssertionError("input list size changed");
        for (int i = 0; i < expected.size(); i++) assertSame(expected.get(i), actual.get(i));
    }

    private static void expectIllegalArgument(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected IllegalArgumentException");
        } catch (IllegalArgumentException expected) {
        }
    }

    private static void expectUnsupported(Runnable action) {
        try {
            action.run();
            throw new AssertionError("expected UnsupportedOperationException");
        } catch (UnsupportedOperationException expected) {
        }
    }

    private static void assertSame(Object expected, Object actual) {
        if (expected != actual) throw new AssertionError("expected identical objects");
    }

    private static void assertNull(Object actual) {
        if (actual != null) throw new AssertionError("expected null");
    }
}

